FONT_PATH = "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"
BOLD_FONT_PATH = "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"

def get_font(size, bold=False):
    path = BOLD_FONT_PATH if bold else FONT_PATH
    return ImageFont.truetype(path, size)

def wrap_text(draw, text, font, max_width):
    words = text.split()
    lines = []
    current_line = []
    for word in words:
        test_line = " ".join(current_line + [word])
        if draw.textlength(test_line, font=font) <= max_width:
            current_line.append(word)
        else:
            if current_line:
                lines.append(" ".join(current_line))
            current_line = [word]
    if current_line:
        lines.append(" ".join(current_line))
    return lines

def draw_scene_bridge(draw, box):
    x0, y0, x1, y1 = box
    draw.rectangle([x0, y0, x1, y1], fill=(224, 242, 254))
    water_y = y1 - 25
    draw.rectangle([x0, water_y, x1, y1], fill=(56, 189, 248))
    draw.rectangle([x0 + 15, water_y + 8, x0 + 35, water_y + 18], fill=(100, 116, 139))
    tower_w = 12
    t1_x = x0 + 30
    t2_x = x1 - 42
    deck_y = y0 + 35
    draw.rectangle([t1_x, y0 + 10, t1_x + tower_w, water_y], fill=(71, 85, 105))
    draw.rectangle([t2_x, y0 + 10, t2_x + tower_w, water_y], fill=(71, 85, 105))
    gap_start = t1_x + 35
    gap_end = t2_x - 15
    draw.rectangle([t1_x, deck_y, gap_start, deck_y + 6], fill=(15, 23, 42))
    draw.rectangle([gap_end, deck_y, t2_x + tower_w, deck_y + 6], fill=(15, 23, 42))
    smoke_x = (gap_start + gap_end) // 2
    draw.ellipse([smoke_x - 8, deck_y - 20, smoke_x + 8, deck_y - 2], fill=(148, 163, 184))
    draw.ellipse([smoke_x - 12, deck_y - 35, smoke_x + 2, deck_y - 15], fill=(203, 213, 225))

def draw_scene_tanker(draw, box):
    x0, y0, x1, y1 = box
    draw.rectangle([x0, y0, x1, y1], fill=(224, 242, 254))
    water_y = y1 - 30
    draw.rectangle([x0, water_y, x1, y1], fill=(14, 116, 144))
    hx0, hy0 = x0 + 15, water_y - 18
    hx1, hy1 = x1 - 25, water_y + 12
    draw.rectangle([hx0, hy0, hx1, hy1], fill=(30, 41, 59))
    draw.rectangle([hx0 + 20, hy0 - 12, hx0 + 50, hy0], fill=(71, 85, 105))
    flame_x = hx0 + 35
    draw.polygon([(flame_x - 10, hy0), (flame_x, hy0 - 20), (flame_x + 10, hy0)], fill=(234, 88, 12))
    draw.polygon([(flame_x - 5, hy0 - 5), (flame_x + 5, hy0 - 28), (flame_x + 12, hy0 - 5)], fill=(250, 204, 21))
    draw.ellipse([flame_x - 15, hy0 - 42, flame_x + 15, hy0 - 22], fill=(15, 23, 42))
    mine_x = x1 - 15
    mine_y = water_y + 8
    draw.ellipse([mine_x - 7, mine_y - 7, mine_x + 7, mine_y + 7], fill=(15, 23, 42))
    for dx, dy in [(-10, 0), (10, 0), (0, -10), (0, 10)]:
        draw.line([mine_x, mine_y, mine_x + dx, mine_y + dy], fill=(15, 23, 42), width=2)

def draw_scene_summit(draw, box):
    x0, y0, x1, y1 = box
    draw.rectangle([x0, y0, x1, y1], fill=(241, 245, 249))
    tx, ty = (x0 + x1) // 2, y1 - 25
    draw.ellipse([tx - 40, ty - 12, tx + 40, ty + 12], fill=(203, 213, 225), outline=(100, 116, 139))
    fxs = [tx - 35, tx, tx + 35]
    colors = [(220, 38, 38), (234, 179, 8), (37, 99, 235)]
    for i, fx in enumerate(fxs):
        draw.line([fx, ty - 5, fx, y0 + 12], fill=(100, 116, 139), width=2)
        draw.polygon([(fx, y0 + 12), (fx + 16, y0 + 18), (fx, y0 + 24)], fill=colors[i])
    draw.rectangle([x0 + 8, y1 - 18, x1 - 8, y1 - 2], fill=(30, 41, 59))
    font = get_font(8, bold=True)
    draw.text((x0 + 11, y1 - 16), "APEC · SHENZHEN", fill=(255, 255, 255), font=font)

def draw_scene_jets(draw, box):
    x0, y0, x1, y1 = box
    draw.rectangle([x0, y0, x1, y1], fill=(186, 230, 253))
    draw.line([x0 + 10, y0 + 20, x0 + 70, y0 + 40], fill=(255, 255, 255), width=3)
    draw.line([x0 + 20, y0 + 45, x0 + 68, y0 + 65], fill=(255, 255, 255), width=3)
    jx1, jy1 = x0 + 60, y0 + 35
    draw.polygon([(jx1 - 12, jy1), (jx1 + 12, jy1 - 3), (jx1 + 15, jy1 + 3)], fill=(71, 85, 105))
    draw.polygon([(jx1 - 4, jy1 - 12), (jx1 + 4, jy1), (jx1 - 2, jy1)], fill=(100, 116, 139))
    jx2, jy2 = x0 + 58, y0 + 60
    draw.polygon([(jx2 - 12, jy2), (jx2 + 12, jy2 - 3), (jx2 + 15, jy2 + 3)], fill=(71, 85, 105))
    draw.polygon([(jx2 - 4, jy2 - 12), (jx2 + 4, jy2), (jx2 - 2, jy2)], fill=(100, 116, 139))

def draw_scene_radar(draw, box):
    x0, y0, x1, y1 = box
    draw.rectangle([x0, y0, x1, y1], fill=(241, 245, 249))
    cx = (x0 + x1) // 2
    draw.rectangle([x0 + 12, y0 + 75, x1 - 12, y1 - 12], fill=(30, 41, 59))
    draw.rectangle([x0 + 6, y0 + 90, x1 - 6, y1 - 12], fill=(30, 41, 59))
    draw.rectangle([cx - 18, y0 + 50, cx + 18, y0 + 75], fill=(30, 41, 59))
    draw.ellipse([cx - 16, y0 + 26, cx + 16, y0 + 58], fill=(30, 41, 59))
    draw.line([cx, y0 + 14, cx, y0 + 26], fill=(30, 41, 59), width=2)
    draw.polygon([(cx, y0 + 14), (cx + 10, y0 + 18), (cx, y0 + 22)], fill=(185, 28, 28))

    bx, by = x1 - 24, y1 - 24
    r = 16
    draw.ellipse([bx - r, by - r, bx + r, by + r], fill=(15, 23, 42), outline=(234, 179, 8))
    draw.ellipse([bx - 3, by - 3, bx + 3, by + 3], fill=(234, 179, 8))
    draw.polygon([(bx, by), (bx - 6, by - 14), (bx + 6, by - 14)], fill=(234, 179, 8))
    draw.polygon([(bx, by), (bx + 12, by + 6), (bx + 5, by + 13)], fill=(234, 179, 8))
    draw.polygon([(bx, by), (bx - 12, by + 6), (bx - 5, by + 13)], fill=(234, 179, 8))

def draw_scene_border(draw, box):
    x0, y0, x1, y1 = box
    draw.rectangle([x0, y0, x1, y1], fill=(226, 232, 240))
    road_x0, road_x1 = x0 + 10, x1 - 10
    draw.rectangle([road_x0, y0 + 8, road_x1, y1 - 8], fill=(100, 116, 139))
    for dy in range(y0 + 12, y1 - 12, 16):
        draw.line([ (road_x0 + road_x1)//2, dy, (road_x0 + road_x1)//2, dy + 8 ], fill=(255, 255, 255), width=2)
    
    bx0, by0 = x0 + 6, y0 + 45
    bx1, by1 = x0 + 38, y0 + 95
    draw.rectangle([bx0 - 2, by0 - 4, bx1 + 2, by0], fill=(51, 65, 85))
    draw.rectangle([bx0, by0, bx1, by1], fill=(203, 213, 225), outline=(71, 85, 105))
    draw.rectangle([bx0 + 6, by0 + 8, bx1 - 6, by0 + 26], fill=(56, 189, 248), outline=(71, 85, 105))

    fx = bx1 + 6
    fy = by0 - 15
    draw.line([fx, fy, fx, by0], fill=(71, 85, 105), width=2)
    flag_w, flag_h = 16, 10
    fh = flag_h // 3
    draw.rectangle([fx, fy, fx + flag_w, fy + fh], fill=(30, 64, 175))
    draw.rectangle([fx, fy + fh, fx + flag_w, fy + 2 * fh], fill=(15, 23, 42))
    draw.rectangle([fx, fy + 2 * fh, fx + flag_w, fy + flag_h], fill=(255, 255, 255))

    gate_y = y0 + 110
    draw.line([road_x0, gate_y, road_x1 - 4, gate_y - 15], fill=(239, 68, 68), width=6)
    draw.line([road_x0 + 8, gate_y - 2, road_x0 + 16, gate_y - 5], fill=(255, 255, 255), width=6)
    draw.line([road_x0 + 28, gate_y - 6, road_x0 + 36, gate_y - 9], fill=(255, 255, 255), width=6)

    sign_box = [x0 + 12, y1 - 26, x1 - 12, y1 - 10]
    draw.rectangle(sign_box, fill=(15, 23, 42))
    font = get_font(8, bold=True)
    tw = draw.textlength("CLOSED", font=font)
    tx = x0 + max(4, ((x1 - x0) - tw) // 2)
    draw.text((tx, y1 - 24), "CLOSED", fill=(255, 255, 255), font=font)

def draw_scene_climate(draw, box):
    x0, y0, x1, y1 = box
    draw.rectangle([x0, y0, x1, y1], fill=(204, 251, 241))
    
    banner_box = [x0 + 6, y0 + 10, x1 - 6, y0 + 42]
    draw.rectangle(banner_box, fill=(13, 148, 136), outline=(15, 23, 42), width=2)
    font = get_font(15, bold=True)
    text = "COP31"
    tw = draw.textlength(text, font=font)
    tx = x0 + max(8, ((x1 - x0) - tw) // 2)
    draw.text((tx, y0 + 14), text, fill=(255, 255, 255), font=font)

    flag_colors = [(220, 38, 38), (37, 99, 235), (234, 179, 8), (22, 101, 52), (168, 85, 247)]
    xs = [x0 + 12, x0 + 26, (x0 + x1)//2, x1 - 26, x1 - 12]
    for i, fx in enumerate(xs):
        draw.line([fx, y0 + 50, fx, y0 + 85], fill=(100, 116, 139), width=2)
        draw.polygon([(fx, y0 + 50), (fx + 12, y0 + 55), (fx, y0 + 60)], fill=flag_colors[i])

    stage_y = y1 - 32
    draw.rectangle([x0 + 6, stage_y, x1 - 6, y1 - 8], fill=(15, 23, 42))
    draw.rectangle([x0 + 6, stage_y - 4, x1 - 6, stage_y], fill=(71, 85, 105))

    cx = (x0 + x1) // 2
    draw.rectangle([cx - 10, stage_y - 22, cx + 10, stage_y], fill=(100, 116, 139))
    draw.ellipse([cx - 7, stage_y - 36, cx + 7, stage_y - 22], fill=(15, 23, 42))

def draw_scene_outage(draw, box):
    x0, y0, x1, y1 = box
    draw.rectangle([x0, y0, x1, y1], fill=(238, 242, 255))
    mx0, my0 = x0 + 18, y0 + 12
    mx1, my1 = x0 + 78, y0 + 62
    draw.rectangle([mx0, my0, mx1, my1], fill=(15, 23, 42), outline=(71, 85, 105), width=2)
    draw.rectangle([mx0 + 6, my0 + 6, mx1 - 6, my1 - 6], fill=(224, 242, 254))
