    draw.ellipse([fx - 6, fy - 6, fx + 6, fy + 6], fill=(255, 255, 255), outline=(15, 23, 42))
    draw.rectangle([x0 + 10, y0 + 12, x0 + 78, y0 + 30], fill=(15, 23, 42))
