def draw_scene_court(draw, box):
    x0, y0, x1, y1 = box
    draw.rectangle([x0, y0, x1, y1], fill=(243, 232, 255))
    bx0, by0 = x0 + 8, y0 + 12
    bx1, by1 = x1 - 8, y1 - 6
    draw.polygon([(bx0 - 2, by0 + 12), ((bx0 + bx1) // 2, by0), (bx1 + 2, by0 + 12)], fill=(109, 40, 217))
    draw.rectangle([bx0, by0 + 12, bx1, by0 + 18], fill=(126, 34, 206))
    for col_x in [bx0 + 8, bx0 + 22, bx0 + 36, bx0 + 50]:
        if col_x + 4 < bx1 - 4:
            draw.rectangle([col_x, by0 + 18, col_x + 4, by1 - 4], fill=(192, 132, 252))
    draw.rectangle([bx0 - 2, by1 - 4, bx1 + 2, by1], fill=(91, 33, 182))

    sx, sy = bx0 + 14, y0 + 26
    draw.line([sx - 6, sy, sx + 6, sy], fill=(30, 41, 59), width=2)
    draw.line([sx, sy - 6, sx, sy], fill=(30, 41, 59), width=2)
    draw.arc([sx - 9, sy, sx - 3, sy + 6], start=0, end=180, fill=(30, 41, 59), width=1)
    draw.arc([sx + 3, sy, sx + 9, sy + 6], start=0, end=180, fill=(30, 41, 59), width=1)

    gx, gy = bx1 - 14, by1 - 14
    draw.line([gx - 5, gy - 5, gx + 5, gy + 5], fill=(15, 23, 42), width=3)
    draw.rectangle([gx + 1, gy - 5, gx + 7, gy + 1], fill=(120, 53, 15))

