def generate_image(output_path):
    width, height = 1024, 1024
    img = Image.new("RGB", (width, height), color=(248, 246, 242))
    draw = ImageDraw.Draw(img)

    banner_h = 64
    draw.rectangle([0, 0, width, banner_h], fill=(17, 24, 39))
    title_font = get_font(22, bold=True)
    sub_font = get_font(11, bold=True)
    draw.text((16, 12), "TUESDAY 17 NOVEMBER 2026", fill=(255, 255, 255), font=title_font)
    draw.text((16, 38), "35 STORIES · 6 CONTINENTS · ONE DAY — THE WORLD IN ONE PICTURE", fill=(234, 179, 8), font=sub_font)

    y_top = 74
    card_w = 324
    card_h = 175
    gap = 10
    left_margin = 16

    for i, story in enumerate(LARGE_STORIES):
        cx = left_margin + i * (card_w + gap)
        cy = y_top
        draw.rectangle([cx, cy, cx + card_w, cy + card_h], fill=(255, 255, 255), outline=(203, 213, 225))
        
        ill_w = 110
        ill_box = (cx + 8, cy + 8, cx + 8 + ill_w, cy + card_h - 8)
        SCENE_FUNCS[story["scene"]](draw, ill_box)

        tx = cx + ill_w + 14
        right_edge = cx + card_w - 8
        bottom_edge = cy + card_h - 8
        tw = right_edge - tx

        tag_font = get_font(9, bold=True)
        tag_w = draw.textlength(story["tag"], font=tag_font) + 8
        draw.rectangle([tx, cy + 8, tx + tag_w, cy + 22], fill=story["tag_color"])
        draw.text((tx + 4, cy + 9), story["tag"], fill=(255, 255, 255), font=tag_font)

        num_font = get_font(10, bold=True)
        draw.ellipse([cx + card_w - 26, cy + 8, cx + card_w - 8, cy + 26], fill=(15, 23, 42))
        draw.text((cx + card_w - 20, cy + 10), str(story["num"]), fill=(255, 255, 255), font=num_font)

        h_font = get_font(12, bold=True)
        h_lines = wrap_text(draw, story["headline"], h_font, tw)
        if len(h_lines) > 2:
            raise ValueError(f"Headline overflow in large story {story['num']}: '{story['headline']}' wraps to {len(h_lines)} lines")
        hy = cy + 28
        for line in h_lines[:2]:
            w = draw.textlength(line, font=h_font)
            if tx < cx or (tx + w) > right_edge or (hy + 15) > bottom_edge:
                raise ValueError(f"Text overflow in large story {story['num']} headline: '{line}'")
            draw.text((tx, hy), line, fill=(15, 23, 42), font=h_font)
            hy += 15

        s_font = get_font(10)
        s_lines = wrap_text(draw, story["summary"], s_font, tw)
        if len(s_lines) > 3:
            raise ValueError(f"Summary overflow in large story {story['num']}: '{story['summary']}' wraps to {len(s_lines)} lines")
        sy = hy + 4
        for line in s_lines[:3]:
            w = draw.textlength(line, font=s_font)
            if tx < cx or (tx + w) > right_edge or (sy + 13) > bottom_edge:
                raise ValueError(f"Text overflow in large story {story['num']} summary: '{line}'")
            draw.text((tx, sy), line, fill=(71, 85, 105), font=s_font)
            sy += 13

    grid_y = y_top + card_h + 10
    m_card_w = 243
    m_card_h = 165
    m_gap = 10

    for i, story in enumerate(MEDIUM_STORIES):
        row = i // 4
        col = i % 4
        cx = left_margin + col * (m_card_w + m_gap)
        cy = grid_y + row * (m_card_h + m_gap)

        draw.rectangle([cx, cy, cx + m_card_w, cy + m_card_h], fill=(255, 255, 255), outline=(203, 213, 225))

        ill_box = (cx + 8, cy + 8, cx + 85, cy + m_card_h - 8)
        SCENE_FUNCS[story["scene"]](draw, ill_box)

        tx = cx + 93
        right_edge = cx + m_card_w - 8
        bottom_edge = cy + m_card_h - 8
        tw = right_edge - tx

        tag_font = get_font(8, bold=True)
        tag_w = draw.textlength(story["tag"], font=tag_font) + 8
        draw.rectangle([tx, cy + 8, tx + tag_w, cy + 20], fill=story["tag_color"])
        draw.text((tx + 3, cy + 9), story["tag"], fill=(255, 255, 255), font=tag_font)

        num_font = get_font(9, bold=True)
        draw.ellipse([cx + m_card_w - 24, cy + 8, cx + m_card_w - 8, cy + 24], fill=(15, 23, 42))
        draw.text((cx + m_card_w - 18, cy + 10), str(story["num"]), fill=(255, 255, 255), font=num_font)

        h_font = get_font(11, bold=True)
        h_lines = wrap_text(draw, story["headline"], h_font, tw)
        if len(h_lines) > 2:
            raise ValueError(f"Headline overflow in medium story {story['num']}: '{story['headline']}' wraps to {len(h_lines)} lines")
        hy = cy + 24
        for line in h_lines[:2]:
            w = draw.textlength(line, font=h_font)
            if tx < cx or (tx + w) > right_edge or (hy + 14) > bottom_edge:
                raise ValueError(f"Text overflow in medium story {story['num']} headline: '{line}'")
            draw.text((tx, hy), line, fill=(15, 23, 42), font=h_font)
            hy += 14

        s_font = get_font(9)
        s_lines = wrap_text(draw, story["summary"], s_font, tw)
        if len(s_lines) > 3:
            raise ValueError(f"Summary overflow in medium story {story['num']}: '{story['summary']}' wraps to {len(s_lines)} lines")
        sy = hy + 3
        for line in s_lines[:3]:
            w = draw.textlength(line, font=s_font)
            if tx < cx or (tx + w) > right_edge or (sy + 12) > bottom_edge:
                raise ValueError(f"Text overflow in medium story {story['num']} summary: '{line}'")
            draw.text((tx, sy), line, fill=(71, 85, 105), font=s_font)
            sy += 12

    bottom_y = grid_y + 2 * (m_card_h + m_gap) + 5
    bottom_h = 370
    draw.rectangle([left_margin, bottom_y, width - left_margin, bottom_y + bottom_h], fill=(255, 255, 255), outline=(203, 213, 225))

    map_x0 = left_margin + 10
    map_y0 = bottom_y + 12
    map_w = 340
    map_h = 240
    map_x1 = map_x0 + map_w
    map_y1 = map_y0 + map_h

    map_font = get_font(11, bold=True)
    draw.text((map_x0, map_y0 - 2), "WHERE IT HAPPENED · WORLD MAP", fill=(15, 23, 42), font=map_font)

    m_box_y0 = map_y0 + 18
    m_box_y1 = map_y1
    draw.rectangle([map_x0, m_box_y0, map_x1, m_box_y1], fill=(224, 242, 254), outline=(148, 163, 184))

    for poly in SIMPLIFIED_LAND:
        screen_pts = []
        for lon, lat in poly:
            x_norm = (lon + 180.0) / 360.0
            y_norm = (90.0 - lat) / 180.0
            sx = map_x0 + x_norm * map_w
            sy = m_box_y0 + y_norm * (m_box_y1 - m_box_y0)
            screen_pts.append((sx, sy))
        if len(screen_pts) >= 3:
            try:
                draw.polygon(screen_pts, fill=(167, 243, 208), outline=(110, 231, 183))
            except Exception:
                pass

    dot_font = get_font(9, bold=True)
    for num, lon, lat, name in MAP_DOTS:
        x_norm = (lon + 180.0) / 360.0
        y_norm = (90.0 - lat) / 180.0
        dx = map_x0 + x_norm * map_w
        dy = m_box_y0 + y_norm * (m_box_y1 - m_box_y0)
        draw.ellipse([dx - 5, dy - 5, dx + 5, dy + 5], fill=(185, 28, 28), outline=(255, 255, 255))
        draw.text((dx + 7, dy - 6), str(num), fill=(15, 23, 42), font=dot_font)

    legend_font = get_font(8, bold=True)
    draw.text((map_x0, m_box_y1 + 4), "Numbered dots match illustrated stories 1-11", fill=(100, 116, 139), font=legend_font)

    list_x0 = map_x1 + 20
    list_y0 = bottom_y + 12
    list_w = width - left_margin - list_x0 - 10

    draw.text((list_x0, list_y0 - 2), "ALSO ON TUESDAY 17 NOVEMBER (STORIES 12–35)", fill=(15, 23, 42), font=map_font)

    list_font = get_font(8.5)
    ly = list_y0 + 20
    for num, text in LIST_STORIES:
        item_text = f"{num}. {text}"
        wrapped = wrap_text(draw, item_text, list_font, list_w)
        for line in wrapped:
            if ly + 11 > bottom_y + bottom_h - 10:
                break
            draw.text((list_x0, ly), line, fill=(51, 65, 85), font=list_font)
            ly += 11
        ly += 2

    footer_y = 1004
    footer_font = get_font(8)
    footer_text = "Every story was reported on Tuesday 17 November 2026; disputed claims are attributed. Sources: Reuters, Al Jazeera, AFP, BBC, AP, Outlook India. Original drawings."
    draw.text((left_margin, footer_y), footer_text, fill=(100, 116, 139), font=footer_font)

    img.save(output_path, "JPEG", quality=90)
    size = os.path.getsize(output_path)
    assert img.size == (1024, 1024), f"Invalid dimensions: {img.size}"
    assert size <= 1048576, f"File size exceeds 1 MiB: {size} bytes"
    print(f"Generated {output_path}: {size} bytes, 1024x1024")

if __name__ == "__main__":
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", ".")
    os.makedirs(out_dir, exist_ok=True)
    out_path = os.path.join(out_dir, "entry.png")
    generate_image(out_path)
